        self.spy_sma = self.SMA(self.spy, 100, Resolution.Daily)
        self.aapl_rsi = self.RSI(
            self.aapl,
            14,
            MovingAverageType.Wilders,
            Resolution.Daily
        )

        self.previous_values = None
        self.red_streak = 0

        self.SetWarmUp(100, Resolution.Daily)

    def OnData(self, data: Slice):
        if self.IsWarmingUp:
            return

        if any(symbol not in data.Bars for symbol in self.symbols):
            return

        if not self.spy_sma.IsReady or not self.aapl_rsi.IsReady:
            return

        spy_close = data.Bars[self.spy].Close
        aapl_close = data.Bars[self.aapl].Close
        spy_sma = self.spy_sma.Current.Value
        aapl_rsi = self.aapl_rsi.Current.Value

        if self.previous_values is None:
            self.previous_values = {
                "spy_close": spy_close,
                "spy_sma": spy_sma,
                "aapl_close": aapl_close
            }
            return

        previous_spy_close = self.previous_values["spy_close"]
        previous_spy_sma = self.previous_values["spy_sma"]
        previous_aapl_close = self.previous_values["aapl_close"]

        if aapl_close < previous_aapl_close:
            self.red_streak += 1
        else:
            self.red_streak = 0

        spy_crosses_above = (
            previous_spy_close <= previous_spy_sma
            and spy_close > spy_sma
        )

        spy_crosses_below = (
            previous_spy_close >= previous_spy_sma
            and spy_close < spy_sma
        )

        if not self.Portfolio[self.spy].Invested and spy_crosses_above:
            quantity = int(
                (self.Portfolio.TotalPortfolioValue * 0.40) / spy_close
            )
            if quantity > 0:
                self.MarketOrder(self.spy, quantity, tag="Strategy A buy")

        if self.Portfolio[self.spy].Invested and spy_crosses_below:
            self.Liquidate(self.spy, "Strategy A sell")

        if not self.Portfolio[self.aapl].Invested and self.red_streak >= 3:
            if self.Portfolio.Cash >= 20000:
                quantity = int(20000 / aapl_close)
                if quantity > 0:
                    self.MarketOrder(self.aapl, quantity, tag="Strategy B buy")

        if self.Portfolio[self.aapl].Invested and aapl_rsi > 60:
            self.Liquidate(self.aapl, "Strategy B sell")

        self.previous_values = {
            "spy_close": spy_close,
            "spy_sma": spy_sma,
            "aapl_close": aapl_close
        }
